// Requests in flight together, through both adapters. Each overlap is made by the fixture, not by timing: a reply
// is held at a named gate until the steps have seen the requests arrive, and released in the order written.

import omp from "../../omp/src/index.ts";
import pi from "../../pi/src/index.ts";
import { scenarios, type Adapter, type Scenario } from "./fake-harness.ts";
import type { Expected, Reply } from "./wire.ts";

const ADAPTERS: readonly Adapter[] = [
  { name: "omp", register: omp, headerHook: false },
  { name: "pi", register: pi, headerHook: true },
];

const HONORED: Reply = { status: 200, headers: { "route-applied": "provider=aurora" }, body: { choices: [] } };
const NOT_HONORED: Reply = { status: 200, body: { choices: [] } };
const REFUSED: Reply = { status: 400, headers: { "route-refused": "reason=unsatisfiable" }, body: { error: "unsatisfiable" } };

// Overlap is made by gates, never by timing: each step waits until the named request has arrived (or is held)
// before the next one starts. A delay before a request departs is therefore unobservable by design; no scenario
// pins one, and no title says anything about timing.
const TWO_SESSIONS = [
  { do: "route", args: "zdr" },
  { do: "open", s: 2 },
  { do: "route", s: 2, args: "notrain" },
  { do: "set", s: 2, model: { baseUrl: "http://{gw}/v1?s=2" } },
  { do: "start", id: "r1" },
  { do: "await-held", gate: "g1" },
  { do: "start", id: "r2", s: 2 },
  { do: "await-held", gate: "g2" },
  { do: "route", args: "" },
  { do: "release", gate: "g2" },
  { do: "finish", id: "r2" },
  { do: "route", args: "" },
  { do: "release", gate: "g1" },
  { do: "finish", id: "r1" },
  { do: "route", args: "" },
  { do: "route", s: 2, args: "" },
] as const;

